import PyPDF2
import os
import re
import json

files = sorted([f for f in os.listdir('.') if f.endswith('.pdf')])

data = {}
for fname in files:
    try:
        with open(fname, 'rb') as f:
            reader = PyPDF2.PdfReader(f)
            text = ""
            for i in range(min(3, len(reader.pages))):
                try:
                    text += reader.pages[i].extract_text() + "\n"
                except:
                    pass
            data[fname] = text[:6000]
    except Exception as e:
        data[fname] = f"ERROR: {e}"

with open('_pdf_text.json', 'w') as f:
    json.dump(data, f, indent=2)

# Better title extraction
def extract_info(text):
    info = {'cat': '?', 'title': '?', 'abs_start': '?'}
    if text.startswith('ERROR'):
        return info
    lines = text.split('\n')
    for i, line in enumerate(lines[:10]):
        m = re.search(r'arXiv:\d+\.\d+v\d+\s*\[([\w\.-]+)\]', line)
        if m:
            info['cat'] = m.group(1)
            # remove the arxiv prefix and date
            prefix = re.match(r'arXiv:\d+\.\d+v\d+\s*\[[\w\.-]+\].*?\d{4}', line)
            if prefix:
                rest = line[prefix.end():].strip()
                if rest and len(rest) > 5:
                    info['title'] = rest
                elif i+1 < len(lines):
                    info['title'] = lines[i+1].strip()
            break
    # Find abstract
    abs_match = re.search(r'(?i)\babstract\b[\.\s:]*', text)
    if abs_match:
        snippet = text[abs_match.end():abs_match.end()+1500]
        info['abs_start'] = snippet
    return info

for fname in files:
    info = extract_info(data[fname])
    print(f"=== {fname} [{info['cat']}] ===")
    print(f"  TITLE: {info['title'][:150]}")
    if info['abs_start'] != '?':
        # First sentence
        first_lines = info['abs_start'][:400].replace('\n', ' ')
        print(f"  ABS:   {first_lines[:300]}")
    print()
